#!/usr/bin/env python3
"""Nosso Combinado 1.9: aplica patch reproduzível à base nativa 1.8 validada."""
import base64,zlib,subprocess,tarfile,io
from pathlib import Path
root=Path(__file__).resolve().parents[1]/'android-v1'
assert (root/'app/src/main/java/com/nossocombinado/app/MainActivity.java').exists(),root
patch=zlib.decompress(base64.b64decode(""))
r=subprocess.run(['patch','-p0','--forward','--batch'],input=patch,cwd=str(root),capture_output=True)
if r.returncode:raise RuntimeError('Falha no patch Android 1.9: '+r.stdout.decode()+r.stderr.decode())
res=root/'app/src/main/res/drawable-nodpi';res.mkdir(parents=True,exist_ok=True)
with tarfile.open(fileobj=io.BytesIO(base64.b64decode("")),mode='r:gz') as tar:
 for item in tar.getmembers():
  if item.name not in {'nosso_icon.png','nc_family_banner.webp','nc_family_1.webp','nc_family_2.webp','nc_family_3.webp'}:raise ValueError(item.name)
  (res/item.name).write_bytes(tar.extractfile(item).read())
grad=root/'app/build.gradle';s=grad.read_text();assert 'versionCode 180' in s and "versionName '1.8.0'" in s
s=s.replace('versionCode 180','versionCode 190').replace("versionName '1.8.0'","versionName '1.9.0'");grad.write_text(s)
print('OK: Nosso Combinado Android 1.9, patch e mídia oficial aplicados')